const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const DEFAULT_EMBLEM = 'data:image/png;base64,';
const STAMP_ASSETS = { government: 'data:image/png;base64,' };
Object.assign(STAMP_ASSETS,{"cpd":"data:image/png;base64,","fbi":"data:image/png;base64,","hospital":"data:image/png;base64,","navy":"data:image/png;base64,"});
const todayISO = () => { const d=new Date(); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,10); };

function autoSignature(name='') {
  const clean = String(name).replace(/\[[^\]]*\]|\u0424\u0418\u041e|ИФ|Имя|Фамилия|должность|судьи|губернатора/gi,'').trim();
  if (!clean) return 'J. Smith';
  const p = clean.split(/\s+/).filter(Boolean);
  if (p.length === 1) return p[0];
  return `${p[0][0] || ''}. ${p[p.length - 1]}`;
}
const signer = (role, name, linkKey='') => ({ role, name, linkKey, signatureMode:'auto', signatureText:autoSignature(name), manualSignature:'' });

