let state = freshState();
let zoom = 1, zoomFitsWidth=true, saveTimer, dragIndex = null;
let stampRequest=0,stampLoading=false,stampMessage='',stampError=false,stampController=null;
function freshState(){return {templateId:null,templateBase:null,quickData:{},org:'СУД ШТАТА RPM',code:'DOC-000',title:'Новый документ',date:todayISO(),location:'Штат RPM',emblem:'',docStyle:'government',sections:[{type:'text',content:'Выберите готовый шаблон или начните редактировать документ вручную.',align:'justify',size:'normal'}],signers:[signer('Автор','Имя Фамилия')],footer:'',stampType:'none',customStampUrl:'',customStampData:'',documentPhotoData:'',portableStampType:'',portableStampData:'',docFont:'georgia',watermark:{enabled:false,text:'',opacity:10,size:88,angle:-28,auto:false}};}

function init(){renderTemplateButtons();restoreDraft();migrateState();bindUI();renderAll();}
function migrateState(){
  state.location=(state.location||'Штат RPM').replace(/Los Santos/gi,'Штат RPM');
  state.org=(state.org||'СУД ШТАТА RPM').replace(/Los Santos/gi,'Штат RPM');
  state.title=state.title||'Новый документ'; state.code=state.code||'DOC-000'; state.date=state.date||todayISO(); state.documentKind=state.documentKind||'';
  state.docStyle=state.docStyle||inferStyle(state.org); state.quickData=state.quickData||{};
  for(const key of ['sections','templateBase'])if(Array.isArray(state[key]))state[key]=state[key].filter(section=>section.content!==REMOVED_CONFIDENTIAL_NOTICE);

  state.sections=(state.sections||[]).map(s=>({type:s.type||'text',content:String(s.content||'').replace(/\u0424\u0418\u041e/g,'ИФ').replace(/Los Santos/gi,'Штат RPM'),align:s.align||((s.type==='text')?'justify':'center'),size:s.size||'normal'}));
  state.signers=(state.signers||[]).map(s=>({...signer(s.role||'Подписант',(s.name||'Имя Фамилия').replace(/\u0424\u0418\u041e/g,'ИФ')),...s,name:(s.name||'Имя Фамилия').replace(/\u0424\u0418\u041e/g,'ИФ'),signatureText:s.signatureText||autoSignature(s.name)}));
}
function inferStyle(org=''){const x=org.toLowerCase();if(x.includes('правитель'))return'government';if(x.includes('fbi'))return'federal';if(x.includes('cpd'))return'cpd';if(x.includes('боль')||x.includes('ems'))return'medical';if(x.includes('вмс')||x.includes('navy'))return'navy';if(x.includes('суд'))return'government';return'classic'}

function bindUI(){
  setupCustomStampControls($('#customStampEditor'));
  $$('.nav-item').forEach(b=>b.onclick=()=>switchPanel(b.dataset.panel));
  $('#newDocumentBtn').onclick=()=>{state=freshState();renderAll();switchPanel('templatesPanel');autosave()};
  $('#saveVersionBtn').onclick=saveVersion; $('#pngBtn').onclick=downloadPNG; if($('#pngZipBtn'))$('#pngZipBtn').onclick=downloadPNGZip; $('#pdfBtn').onclick=downloadPDF;
  [['orgInput','org'],['codeInput','code'],['titleInput','title'],['dateInput','date'],['footerInput','footer'],['stampTypeInput','stampType'],['styleInput','docStyle']].forEach(([id,key])=>{const el=$('#'+id);if(el)el.addEventListener('input',e=>{state[key]=e.target.value;if(key==='stampType'){if($('#quickStamp'))$('#quickStamp').value=state.stampType;syncCustomStampControls()}if(key==='org'&&!state.docStyle)state.docStyle=inferStyle(state.org);renderPreview();autosave()})});
  $('#emblemInput').onchange=handleEmblem; $('#removeEmblemBtn').onclick=()=>{state.emblem='';renderPreview();autosave()};
  $('#addSignerBtn').onclick=()=>{state.signers.push(signer('Подписант','Имя Фамилия'));renderSigners();renderPreview();autosave()};
  $$('[data-add-section]').forEach(b=>b.onclick=()=>{const type=b.dataset.addSection;state.sections.push({type,content:type==='divider'?'':type==='heading'?'НОВЫЙ РАЗДЕЛ:':'Введите текст...',align:type==='heading'?'center':'justify',size:'normal'});renderSections();renderPreview();autosave()});
  $('#zoomOutBtn').onclick=()=>setZoom(Math.max(.2,zoom-.1));$('#zoomInBtn').onclick=()=>setZoom(Math.min(1.4,zoom+.1));
  $('#openEditorBtn').onclick=()=>switchPanel('editorPanel');
  $('#exportHistoryBtn').onclick=exportHistory; $('#importHistoryInput').onchange=importHistory;
}
function switchPanel(id){if(id==='rpPanel'){if($('#quickPanel').classList.contains('active-panel')&&_liveQuickTimer){clearTimeout(_liveQuickTimer);_liveQuickTimer=null;applyQuickData(true)}renderRPPanel();$('#rpPanel').scrollIntoView({behavior:'smooth',block:'nearest'});$('#rpCopyNextBtn').focus({preventScroll:true});return}if(id!=='quickPanel'&&$('#quickPanel').classList.contains('active-panel')&&_liveQuickTimer){clearTimeout(_liveQuickTimer);_liveQuickTimer=null;applyQuickData(true)}$$('.panel').forEach(p=>p.classList.toggle('active-panel',p.id===id));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.panel===id));if(id==='savedPanel')renderSavedList();if(id==='quickPanel')renderQuickForm();if(id==='rpPanel')renderRPPanel()}

function renderTemplateButtons(){const map={warrant:'#warrantTemplates',government:'#governmentTemplates',court:'#courtTemplates',contract:'#contractTemplates',hospital:'#hospitalTemplates'};Object.values(map).forEach(id=>$(id).innerHTML='');TEMPLATES.forEach(t=>{const b=document.createElement('button');b.className='template-card';b.dataset.template=t.id;b.innerHTML=`<strong>${escapeHtml(t.name)}</strong><span>${escapeHtml(t.desc)}</span>`;b.onclick=()=>applyTemplate(t.id);$(map[t.group]).appendChild(b)})}
function applyTemplate(id){const t=TEMPLATES.find(x=>x.id===id);if(!t)return;state={...freshState(),templateId:t.id,org:t.org,code:t.code,title:t.title,date:todayISO(),location:'Штат RPM',docStyle:t.style,documentKind:t.name,sections:t.sections.map(([type,content])=>({type,content,align:type==='heading'?'center':'justify',size:'normal'})),signers:t.signers.map(([r,n,key])=>signer(r,n,key||'')),stampType:t.stamp||'none'};state.templateBase=JSON.parse(JSON.stringify(state.sections));state.quickData={};if(['contract-family','contract-business'].includes(t.id))state.quickData['время оформления']=new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Kyiv'});if(t.group==='hospital'){state.docFont='inter';state.quickData['дата осмотра']=formatDate(state.date);state.quickData['дата операции']=formatDate(state.date);}renderAll();switchPanel('quickPanel');autosave();toast('Шаблон загружен')}

function renderAll(){migrateState();$$('.template-card').forEach(b=>{const chosen=b.dataset.template===state.templateId;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen))});$('#workspaceTitle').textContent=state.title||'Новый документ';renderEditorFields();renderQuickForm();renderSections();renderSigners();renderPreview();renderRPPanel()}
function renderEditorFields(){$('#orgInput').value=state.org||'';$('#codeInput').value=state.code||'';$('#titleInput').value=state.title||'';$('#dateInput').value=state.date||todayISO();$('#dateInput').disabled=false;$('#footerInput').value=state.footer||'';$('#stampTypeInput').value=state.stampType||'none';$('#styleInput').value=state.docStyle||'classic';syncCustomStampControls()}
function extractPlaceholders(sections){const seen=new Set(),out=[];sections.forEach(s=>{for(const m of String(s.content||'').matchAll(/\[([^\]]+)\]/g)){const key=m[1].trim();if(!seen.has(key)){seen.add(key);out.push(key)}}});return out}
function renderQuickForm(){const root=$('#quickFields');if(!root)return;root.innerHTML='';const t=TEMPLATES.find(x=>x.id===state.templateId);$('#quickTitle').textContent=t?t.name:'Быстрое заполнение';
  const meta=document.createElement('div');meta.className='quick-meta-grid';meta.innerHTML=`<label>Номер документа<input id="quickCode" type="text" value="${escapeAttr(state.code||'')}"></label><label>Дата документа<input id="quickDate" type="date" value="${escapeAttr(state.date||todayISO())}"></label><label>Стиль документа<select id="quickStyle"><option value="government">Government</option><option value="court">Судебный</option><option value="federal">FBI / Federal</option><option value="cpd">CPD</option><option value="medical">Медицинский</option><option value="hospital">Медицинский v2</option><option value="navy">ВМС</option><option value="classic">Классический</option></select></label><label>Штамп<select id="quickStamp"><option value="government">Government</option><option value="cpd">CPD</option><option value="fbi">FBI</option><option value="hospital">Больница</option><option value="navy">ВМС</option><option value="custom">Свой штамп по ссылке</option><option value="none">Без штампа</option></select></label>`;root.appendChild(meta);const customStamp=document.createElement('div');customStamp.dataset.customStamp='quick';customStamp.className='custom-stamp-settings';root.appendChild(customStamp);setupCustomStampControls(customStamp);const quickStyle=meta.querySelector('#quickStyle');quickStyle.value=state.docStyle||'government';quickStyle.onchange=e=>{state.docStyle=e.target.value;const styleInput=$('#styleInput');if(styleInput)styleInput.value=state.docStyle;renderPreview();autosave()};const quickStamp=meta.querySelector('#quickStamp');quickStamp.value=state.stampType||'government';quickStamp.onchange=e=>{state.stampType=e.target.value;const stampInput=$('#stampTypeInput');if(stampInput)stampInput.value=state.stampType;syncCustomStampControls();renderPreview();autosave()};
  const isWarrant=!!(t&&t.group==='warrant');
  if(isWarrant){const issuer=document.createElement('div');issuer.className='quick-signer-section warrant-issuer-card compact-issuer-card';issuer.innerHTML=`<div class="quick-subtitle">Выдача ордера</div><div class="quick-meta-grid warrant-issuer-grid"><label>Организация<select id="quickWarrantIssuerOrg"><option>Суд штата RPM</option><option>FBI RPM</option><option>CPD RPM</option><option>Правительство штата RPM</option><option>ВМС RPM</option><option>Больница штата RPM</option></select></label><label>Должность<input id="quickWarrantIssuerRole" type="text" placeholder="Должность составителя"></label><label>Имя Фамилия<input id="quickWarrantIssuerName" type="text" placeholder="Имя Фамилия"></label></div></div>`;root.appendChild(issuer);const org=issuer.querySelector('#quickWarrantIssuerOrg'),role=issuer.querySelector('#quickWarrantIssuerRole'),name=issuer.querySelector('#quickWarrantIssuerName');const oldMode=state.quickData.__warrantIssuerMode||'court';org.value=state.quickData.__warrantIssuerOrg||(oldMode==='court'?'Суд штата RPM':'FBI RPM');if(!Array.from(org.options).some(o=>o.value===org.value))org.value='FBI RPM';const isCourt=()=>org.value==='Суд штата RPM';const defaultRoleForOrg=v=>{if(v==='Суд штата RPM')return 'Судья штата RPM';if(v==='FBI RPM')return 'Инспектор FBI штата RPM';if(v==='CPD RPM')return 'Сотрудник CPD штата RPM';if(v==='Правительство штата RPM')return 'Губернатор штата RPM';if(v==='ВМС RPM')return 'Генерал ВМС штата RPM';if(v==='Больница штата RPM')return 'Руководитель Больницы штата RPM';return 'Уполномоченное лицо'};const legacyCourtRole=state.quickData.__warrantIssuerRole||state.quickData.__warrantCourtRole||'';const legacyCourtName=state.quickData.__warrantIssuerName||state.quickData.__warrantCourtName||'';role.value=(isCourt()?legacyCourtRole:state.quickData.__warrantIssuerRole)||defaultRoleForOrg(org.value);name.value=(isCourt()?legacyCourtName:state.quickData.__warrantIssuerName)||((state.signers[0]&&state.signers[0].name!=='Имя Фамилия')?state.signers[0].name:'');const syncIssuer=()=>{const prevOrg=state.quickData.__warrantIssuerOrg;state.quickData.__warrantIssuerOrg=org.value;state.quickData.__warrantIssuerMode=isCourt()?'court':'author';if(prevOrg!==org.value){role.value=defaultRoleForOrg(org.value)}state.quickData.__warrantIssuerRole=role.value;state.quickData.__warrantIssuerName=name.value;autosave()};org.onchange=()=>{syncIssuer();syncWarrantCircumstanceAuthor();scheduleLiveQuick()};role.oninput=()=>{state.quickData.__warrantIssuerRole=role.value;autosave()};name.oninput=()=>{state.quickData.__warrantIssuerName=name.value;autosave()};role.onchange=role.oninput;name.onchange=name.oninput;syncIssuer()}
  const base=state.templateBase||state.sections;const fields=extractPlaceholders(base);if(!fields.length){const empty=document.createElement('div');empty.className='quick-empty';empty.textContent='Все поля заполнены. Текст можно изменить в редакторе.';root.appendChild(empty)}
  fields.forEach(key=>{const label=document.createElement('label');const title=placeholderLabels[key]||capitalize(key);const multiline=/заключение|рекомендац|жалобы|причина смерти|обстоятель|положение|территор|основан|просьб|доказ|обязан|прав[аы]|решение|огранич|имущество|поручение|перечень|лица|объём|услови|ответствен|порядок|услуг|товар/i.test(key);let control='';if(key==='структура'){control=`<select data-quick="${escapeAttr(key)}"><option value="">Выберите структуру</option><option>FBI RPM</option><option>CPD RPM</option><option>Правительство штата RPM</option><option>Суд штата RPM</option><option>ВМС RPM</option><option>Больница штата RPM</option></select>`}else if(key==='статус ордера'){control=`<select data-quick="${escapeAttr(key)}"><option value="">Открытый</option><option value="Ордер закрыт для общественности.">Закрытый</option></select>`}else{control=multiline?`<textarea data-quick="${escapeAttr(key)}" rows="3" placeholder="${escapeAttr(title)}"></textarea>`:`<input data-quick="${escapeAttr(key)}" type="text" placeholder="${escapeAttr(title)}">`}label.innerHTML=`${escapeHtml(title)}${control}`;const input=label.querySelector('[data-quick]');input.value=state.quickData[key]||'';input.oninput=e=>{state.quickData[key]=e.target.value;autosave()};root.appendChild(label)});
  if(!isWarrant){const signerWrap=document.createElement('div');signerWrap.className='quick-signer-section';const signerTitle=document.createElement('div');signerTitle.className='quick-subtitle';signerTitle.textContent=state.signers.length>1?'Подписи сторон':'Подписант';signerWrap.appendChild(signerTitle);state.signers.forEach((s,i)=>{const row=document.createElement('div');row.className='quick-meta-grid signer-quick-grid';if(s.linkKey){row.innerHTML=`<label>${escapeHtml(s.role)}<input type="text" value="${escapeAttr(state.quickData[s.linkKey]||'')}" placeholder="Заполняется из поля «${escapeAttr(placeholderLabels[s.linkKey]||s.linkKey)}»" disabled></label><label>Роль<input type="text" value="${escapeAttr(s.role||'')}" disabled></label>`}else{row.innerHTML=`<label>Имя Фамилия<input data-quick-signer-name="${i}" type="text" placeholder="Имя Фамилия" value="${escapeAttr(s.name||'')}"></label><label>Должность / роль<input data-quick-signer-role="${i}" type="text" placeholder="Должность" value="${escapeAttr(s.role||'')}"></label>`}signerWrap.appendChild(row)});root.appendChild(signerWrap)}
}
function warrantAuthorTitle(template,org){const x=(org||'').toLowerCase();if(x.includes('fbi'))return 'ОРДЕР ФБР';if(x.includes('cpd'))return 'ОРДЕР CPD';if(x.includes('правитель'))return 'ОРДЕР ПРАВИТЕЛЬСТВА';if(x.includes('вмс')||x.includes('navy'))return 'ОРДЕР ВМС';if(x.includes('боль'))return 'ОРДЕР БОЛЬНИЦЫ';if(x.includes('суд'))return 'СУДЕБНЫЙ ОРДЕР';return `ОРДЕР ${(org||'').toUpperCase()}`.replace(/\s+/g,' ').trim()}
function applyQuickData(silent=false){const signatureSettings=state.signers.map(s=>({signatureMode:s.signatureMode,manualSignature:s.manualSignature,customText:s.signatureText!==autoSignature(s.name)?s.signatureText:null}));const t=TEMPLATES.find(x=>x.id===state.templateId);const isWarrant=!!(t&&t.group==='warrant');const base=JSON.parse(JSON.stringify(state.templateBase||state.sections));state.sections=base.map(s=>({...s,content:String(s.content||'').replace(/\[([^\]]+)\]/g,(all,key)=>{key=key.trim();if(key==='статус ордера'){return (state.quickData[key]||'').trim()}const v=(state.quickData[key]||'').trim();return v||all})})).filter(s=>!(s.type==='notice'&&!String(s.content||'').trim()));const qc=$('#quickCode'),qd=$('#quickDate');if(qc)state.code=qc.value.trim()||state.code;if(qd)state.date=qd.value||todayISO();if(isWarrant){const org=(state.quickData.__warrantIssuerOrg||'Суд штата RPM').trim(),isCourt=org==='Суд штата RPM',role=(state.quickData.__warrantIssuerRole||(isCourt?'Судья штата RPM':'Инспектор FBI штата RPM')).trim(),name=(state.quickData.__warrantIssuerName||'Имя Фамилия').trim();state.quickData.__warrantIssuerMode=isCourt?'court':'author';if(isCourt){state.org='СУД ШТАТА RPM';state.title='СУДЕБНЫЙ ОРДЕР';state.signers=[signer(role,name)];state.signers[0].signatureText=autoSignature(name)}else{state.org=org;state.title=warrantAuthorTitle(t,org);const firstText=state.sections.find(s=>s.type==='text');if(firstText)firstText.content=`Я, ${role} ${name}, рассмотрев материалы, относящиеся к обстоятельствам выдачи настоящего ордера, прихожу к выводу о наличии законных оснований для его выдачи.`;state.signers=[signer(role,name)];state.signers[0].signatureText=autoSignature(name)}}else{state.signers.forEach((s,i)=>{if(s.linkKey){const linked=(state.quickData[s.linkKey]||'').trim();if(linked){s.name=linked;s.signatureText=autoSignature(linked)}}else{const q=document.querySelector(`[data-quick-signer-name="${i}"]`),qr=document.querySelector(`[data-quick-signer-role="${i}"]`);if(q){s.name=q.value.trim()||'Имя Фамилия';s.signatureText=autoSignature(s.name)}if(qr)s.role=qr.value.trim()||s.role}});}if(isWarrant){const closed=String(state.quickData['статус ордера']||'').includes('закрыт');if(closed){const access=String(state.quickData.__confidentialAccess||'').trim();if(access)state.sections.push({type:'notice',content:`Доступ к закрытому ордеру: ${access}`,align:'left',size:'normal'});if(!state.watermark||state.watermark.auto||!state.watermark.enabled){state.watermark={...(state.watermark||{}),enabled:true,text:'CONFIDENTIAL',opacity:9,size:84,angle:-28,auto:true}}}else if(state.watermark&&state.watermark.auto){state.watermark.enabled=false;state.watermark.auto=false}}state.signers.forEach((s,i)=>{const old=signatureSettings[i];if(old){s.signatureMode=old.signatureMode||'auto';s.manualSignature=old.manualSignature||'';if(old.customText!==null)s.signatureText=old.customText}});refreshQuickSignatureSamples();renderEditorFields();renderSections();renderSigners();renderPreview();autosave();if(!silent)toast('Данные подставлены')}


function renderSections(){const root=$('#sectionList');root.innerHTML='';state.sections.forEach((s,i)=>{const d=document.createElement('div');d.className='section-editor';d.draggable=true;d.dataset.index=i;const typeName={heading:'Заголовок',text:'Текст',notice:'Выделение',divider:'Линия'}[s.type]||s.type;const legalTools=s.type==='text'?`<span class="toolbar-separator"></span><select class="format-select legal-phrase-select" data-legal-phrase title="Юридическая формулировка"><option value="">⚖ Юр. формулировка…</option>${LEGAL_PHRASES.map((x,idx)=>`<option value="${idx}">${escapeHtml(x[0])}</option>`).join('')}</select><button class="format-btn legal-insert-btn" data-insert-legal title="Вставить формулировку в позицию курсора">+ Вставить</button>`:'';d.innerHTML=`<div class="section-editor-head"><div><span class="drag-handle">⠿</span><span class="section-type">${typeName}</span></div><div class="section-actions"><button class="mini-btn" data-up>↑</button><button class="mini-btn" data-down>↓</button><button class="mini-btn danger" data-del>×</button></div></div>${s.type==='divider'?'':`<div class="rich-toolbar"><button class="format-btn" data-wrap="b"><b>B</b></button><button class="format-btn" data-wrap="i"><i>I</i></button><button class="format-btn" data-wrap="u"><u>U</u></button><button class="format-btn" data-list="ul">• список</button><button class="format-btn" data-list="ol">1. список</button><select class="format-select" data-align><option value="left">Слева</option><option value="center">Центр</option><option value="right">Справа</option><option value="justify">По ширине</option></select><select class="format-select" data-size><option value="small">Мелкий</option><option value="normal">Обычный</option><option value="large">Крупный</option></select>${legalTools}</div><textarea data-content rows="${s.type==='heading'?2:5}">${escapeHtml(s.content)}</textarea>`}`;
    const ta=d.querySelector('[data-content]');if(ta){ta.oninput=e=>{state.sections[i].content=e.target.value;renderPreview();autosave()};const al=d.querySelector('[data-align]'),sz=d.querySelector('[data-size]');al.value=s.align||'justify';sz.value=s.size||'normal';al.onchange=e=>{state.sections[i].align=e.target.value;renderPreview();autosave()};sz.onchange=e=>{state.sections[i].size=e.target.value;renderPreview();autosave()};d.querySelectorAll('[data-wrap]').forEach(b=>b.onclick=()=>wrapSelection(ta,b.dataset.wrap,i));d.querySelectorAll('[data-list]').forEach(b=>b.onclick=()=>listSelection(ta,b.dataset.list,i));const phraseSel=d.querySelector('[data-legal-phrase]'),phraseBtn=d.querySelector('[data-insert-legal]');if(phraseSel&&phraseBtn){phraseBtn.onclick=()=>insertLegalPhraseAtCursor(ta,phraseSel,i);phraseSel.onchange=()=>{if(phraseSel.value!=='')insertLegalPhraseAtCursor(ta,phraseSel,i)}}}
    d.querySelector('[data-del]').onclick=()=>{state.sections.splice(i,1);renderSections();renderPreview();autosave()};d.querySelector('[data-up]').onclick=()=>moveSection(i,i-1);d.querySelector('[data-down]').onclick=()=>moveSection(i,i+1);
    d.ondragstart=()=>{dragIndex=i;d.classList.add('dragging')};d.ondragend=()=>{dragIndex=null;d.classList.remove('dragging');$$('.section-editor').forEach(x=>x.classList.remove('drag-over'))};d.ondragover=e=>{e.preventDefault();d.classList.add('drag-over')};d.ondragleave=()=>d.classList.remove('drag-over');d.ondrop=e=>{e.preventDefault();d.classList.remove('drag-over');if(dragIndex!==null&&dragIndex!==i)moveSection(dragIndex,i)};
    root.appendChild(d)})}
function moveSection(from,to){if(to<0||to>=state.sections.length)return;const [x]=state.sections.splice(from,1);state.sections.splice(to,0,x);renderSections();renderPreview();autosave()}
function wrapSelection(ta,tag,i){const a=ta.selectionStart,b=ta.selectionEnd,txt=ta.value,sel=txt.slice(a,b)||'текст';ta.value=txt.slice(0,a)+`<${tag}>${sel}</${tag}>`+txt.slice(b);state.sections[i].content=ta.value;renderPreview();autosave();ta.focus()}
function listSelection(ta,type,i){const a=ta.selectionStart,b=ta.selectionEnd,txt=ta.value,sel=(txt.slice(a,b)||'пункт 1\nпункт 2').split(/\n+/).filter(Boolean).map(x=>`<li>${x}</li>`).join('');ta.value=txt.slice(0,a)+`<${type}>${sel}</${type}>`+txt.slice(b);state.sections[i].content=ta.value;renderPreview();autosave();ta.focus()}
function insertLegalPhraseAtCursor(ta,select,i){const idx=Number(select.value);if(!Number.isFinite(idx)||!LEGAL_PHRASES[idx])return;const phrase=LEGAL_PHRASES[idx][1],txt=ta.value||'',a=Number.isFinite(ta.selectionStart)?ta.selectionStart:txt.length,b=Number.isFinite(ta.selectionEnd)?ta.selectionEnd:a;const before=txt.slice(0,a),after=txt.slice(b),lead=before&&!before.endsWith('\n')?'\n\n':'',trail=after&&!after.startsWith('\n')?'\n\n':'';const insertion=lead+phrase+trail;ta.value=before+insertion+after;state.sections[i].content=ta.value;const pos=(before+lead+phrase).length;renderPreview();autosave();ta.focus();ta.setSelectionRange(pos,pos);select.value='';toast('Формулировка вставлена в текст')}

function renderSigners(){const root=$('#signerList');root.innerHTML='';state.signers.forEach((s,i)=>{const card=document.createElement('div');card.className='signer-card';card.innerHTML=`<div class="signer-card-top"><strong>Подписант ${i+1}</strong><button class="mini-btn danger" data-remove>Удалить</button></div><label>Имя Фамилия<input data-name type="text" value="${escapeAttr(s.name||'')}"></label><label>Должность / роль<input data-role type="text" value="${escapeAttr(s.role||'')}"></label><label>Подпись<select data-mode><option value="auto">Автоматическая</option><option value="manual">Рукописная</option><option value="none">Без подписи</option></select></label><div class="auto-signature-settings"><label>Текст подписи<input data-sigtext type="text" value="${escapeAttr(s.signatureText||autoSignature(s.name))}"></label><div class="signature-sample" data-sample>${escapeHtml(s.signatureText||autoSignature(s.name))}</div></div><div class="manual-signature-settings hidden"><div class="signature-toolbar"><span class="help">Нарисуйте подпись</span><button class="mini-btn" data-clear>Очистить</button></div><canvas data-canvas width="640" height="190"></canvas></div>`;const mode=card.querySelector('[data-mode]');mode.value=s.signatureMode||'auto';const refreshMode=()=>{card.querySelector('.auto-signature-settings').classList.toggle('hidden',mode.value!=='auto');card.querySelector('.manual-signature-settings').classList.toggle('hidden',mode.value!=='manual')};refreshMode();mode.onchange=()=>{state.signers[i].signatureMode=mode.value;refreshMode();if(mode.value==='manual')setupSignerCanvas(card.querySelector('[data-canvas]'),i,card.querySelector('[data-clear]'));renderPreview();autosave()};card.querySelector('[data-name]').oninput=e=>{state.signers[i].name=e.target.value;const generated=autoSignature(e.target.value);state.signers[i].signatureText=generated;card.querySelector('[data-sigtext]').value=generated;card.querySelector('[data-sample]').textContent=generated;renderPreview();autosave()};card.querySelector('[data-role]').oninput=e=>{state.signers[i].role=e.target.value;renderPreview();autosave()};card.querySelector('[data-sigtext]').oninput=e=>{state.signers[i].signatureText=e.target.value;card.querySelector('[data-sample]').textContent=e.target.value;renderPreview();autosave()};card.querySelector('[data-remove]').onclick=()=>{state.signers.splice(i,1);renderSigners();renderPreview();autosave()};root.appendChild(card);if(mode.value==='manual')setupSignerCanvas(card.querySelector('[data-canvas]'),i,card.querySelector('[data-clear]'))})}
function setupSignerCanvas(c,i,clearBtn){if(!c)return;const ctx=c.getContext('2d');ctx.lineWidth=4;ctx.lineCap='round';ctx.strokeStyle='#12458d';ctx.clearRect(0,0,c.width,c.height);if(state.signers[i].manualSignature){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0,c.width,c.height);img.src=state.signers[i].manualSignature}let drawing=false;const pos=e=>{const r=c.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return{x:(p.clientX-r.left)*c.width/r.width,y:(p.clientY-r.top)*c.height/r.height}};const start=e=>{drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()};const move=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()};const end=()=>{if(!drawing)return;drawing=false;state.signers[i].manualSignature=c.toDataURL('image/png');renderPreview();autosave()};c.onmousedown=start;c.onmousemove=move;c.onmouseup=end;c.onmouseleave=end;c.ontouchstart=start;c.ontouchmove=move;c.ontouchend=end;clearBtn.onclick=()=>{ctx.clearRect(0,0,c.width,c.height);state.signers[i].manualSignature='';renderPreview();autosave()}}

function renderPreview(){clearTimeout(window._rpmRender);window._rpmRender=setTimeout(buildPages,25);clearTimeout(window._rpmRPRefresh);window._rpmRPRefresh=setTimeout(()=>renderRPPanel(),250)}
function createPage(first=false,compact=false){const p=document.createElement('article');const isConfidential=String(state.quickData?.['статус ордера']||'').includes('закрыт');p.className=`document-page style-${state.docStyle||'classic'} font-${state.docFont||'georgia'}${compact?' compact-document':''}${state.templateId==='warrant-search'?' search-warrant':''}${isConfidential?' confidential-document':''}`;const inner=document.createElement('div');inner.className='page-inner';p.appendChild(inner);if(state.watermark&&state.watermark.enabled&&String(state.watermark.text||'').trim()){const wm=document.createElement('div');wm.className='doc-watermark';wm.textContent=state.watermark.text;wm.style.setProperty('--wm-opacity',String((Number(state.watermark.opacity)||10)/100));wm.style.setProperty('--wm-size',(Number(state.watermark.size)||88)+'px');wm.style.setProperty('--wm-angle',(Number(state.watermark.angle)||-28)+'deg');p.appendChild(wm)}if(isConfidential){const flag=document.createElement('div');flag.className='confidential-flag';flag.textContent='CONFIDENTIAL';p.appendChild(flag)}const date=state.date||todayISO();if(first)inner.innerHTML=`<header class="doc-header"><div class="doc-emblem-wrap"><img class="doc-emblem" src="${state.emblem||DEFAULT_EMBLEM}" alt="Герб"></div><div class="doc-country">СОЕДИНЕННЫЕ ШТАТЫ АМЕРИКИ</div><div class="doc-org">${escapeHtml((state.org||'').toUpperCase())}</div></header><div class="doc-rule"></div><div class="doc-code">${escapeHtml(state.code||'—')}${state.documentKind?` <span class="doc-code-sep">|</span> ${escapeHtml(state.documentKind)}`:''}</div><h2 class="doc-title">${escapeHtml(state.title||'Без названия')}</h2><div class="doc-title-rule"></div><div class="doc-meta-line doc-meta-date-only"><span>${formatDate(date)}</span></div><div class="doc-flow"></div>`;else inner.innerHTML=`<div class="continuation-head"><img src="${state.emblem||DEFAULT_EMBLEM}"><span>${escapeHtml(state.code||'—')} · ${escapeHtml(state.title||'Документ')}</span><span>ПРОДОЛЖЕНИЕ</span></div><div class="doc-flow"></div>`;if(first&&state.docStyle==='hospital'){const header=p.querySelector('.doc-header');header.innerHTML=`<div class="hospital-symbol" aria-hidden="true">+</div><div class="hospital-header-copy"><div class="hospital-kicker">МЕДИЦИНСКАЯ ДОКУМЕНТАЦИЯ</div><div class="hospital-brand">${escapeHtml(state.org||'RPM SOUTH HOSPITAL')}</div></div><div class="hospital-header-region">RPM<br><span>SOUTH</span></div>`;p.classList.toggle('hospital-death',state.templateId==='hospital-death');}return p}
function sanitizeRich(raw=''){const holder=document.createElement('div');holder.innerHTML=String(raw).replace(/\n/g,'<br>');const allowed=new Set(['B','STRONG','I','EM','U','BR','UL','OL','LI','P']);[...holder.querySelectorAll('*')].forEach(el=>{if(!allowed.has(el.tagName)){el.replaceWith(document.createTextNode(el.textContent||''));return}[...el.attributes].forEach(a=>el.removeAttribute(a.name))});return holder.innerHTML}
function createFlowBlock(item){const d=document.createElement('div');if(item.kind==='section'){d.className=`doc-section ${item.type} align-${item.align||'justify'} size-${item.size||'normal'}`;if(item.type!=='divider')d.innerHTML=sanitizeRich(item.content)}else if(item.kind==='signers'){const count=Math.max(1,item.signers.length);d.className=`doc-signers signer-count-${Math.min(count,3)}${count>1?' multi-signers':''}`;item.signers.forEach(s=>{const x=document.createElement('div');x.className='doc-signer';let sig='';if(s.signatureMode==='auto')sig=`<div class="auto-signature">${escapeHtml(s.signatureText||autoSignature(s.name))}</div>`;if(s.signatureMode==='manual'&&s.manualSignature)sig=`<img class="manual-signature" src="${s.manualSignature}">`;x.innerHTML=`<div class="signer-identity"><div class="doc-signer-role">${escapeHtml(s.role)}</div><div class="doc-signer-name">${escapeHtml(s.name)}</div></div><div class="signer-signature">${sig}<div class="signature-line"></div><small>ПОДПИСЬ</small></div>`;d.appendChild(x)})}else if(item.kind==='document-photo'){d.className='hospital-photo-block';const heading=document.createElement('h3');heading.textContent='ФОТОГРАФИЯ УМЕРШЕГО';d.appendChild(heading);if(/^data:image\/png;base64,/.test(state.documentPhotoData||'')){const img=document.createElement('img');img.src=state.documentPhotoData;img.alt='Фотография умершего';const frame=document.createElement('div');frame.className='hospital-photo-frame';frame.appendChild(img);d.appendChild(frame)}else{const empty=document.createElement('div');empty.className='hospital-photo-empty';empty.textContent='Фотография не добавлена';d.appendChild(empty)}}else if(item.kind==='stamp'){d.className='doc-stamp-row';const s=document.createElement('div');s.className='stamp-preview';if(stampSource()){const img=document.createElement('img');img.src=stampSource();img.alt=state.stampType==='custom'?'Свой штамп':'Штамп '+state.stampType.toUpperCase();s.appendChild(img)}else{const names={cpd:'CPD RPM',fbi:'FBI RPM',hospital:'HOSPITAL RPM',navy:'NAVY RPM'};s.innerHTML=`<div class="stamp-placeholder">${escapeHtml(names[state.stampType]||state.stampType.toUpperCase())}</div>`}d.appendChild(s)}else if(item.kind==='footer'){d.className='doc-footer';d.textContent=state.footer||''}return d}
function blockFits(flow,node){flow.appendChild(node);const page=flow.closest('.document-page'),ok=node.getBoundingClientRect().bottom-page.getBoundingClientRect().top<=page.clientHeight-72;flow.removeChild(node);return ok}
function plainText(html=''){const d=document.createElement('div');d.innerHTML=html;return d.textContent||d.innerText||''}
function splitTextToFit(flow,item){const text=plainText(item.content),words=text.split(/(\s+)/);if(words.length<2)return[null,item];let lo=1,hi=words.length,best=0;while(lo<=hi){const mid=Math.floor((lo+hi)/2),node=createFlowBlock({...item,content:words.slice(0,mid).join('')});if(blockFits(flow,node)){best=mid;lo=mid+1}else hi=mid-1}if(!best)return[null,item];const a=words.slice(0,best).join('').trimEnd(),b=words.slice(best).join('').trimStart();return[a?{...item,content:a}:null,b?{...item,content:b}:null]}
function headingHasRoom(flow,heading,next){if(!next||next.kind!=='section')return true;const h=createFlowBlock(heading);const teaser=createFlowBlock({...next,content:plainText(next.content).slice(0,180)});const wrap=document.createElement('div');wrap.appendChild(h);wrap.appendChild(teaser);return blockFits(flow,wrap)}
function addDecorations(page,index,total){const pn=document.createElement('div');pn.className='page-number';pn.textContent=`${index+1} / ${total}`;page.appendChild(pn)}
function buildPages(){
  // Pagination is measured at native A4 size, independent of preview zoom.
  $('#pagesContainer').style.transform='none';
  const renderAttempt=(compact=false)=>{
    const container=$('#pagesContainer');container.innerHTML='';
    const items=state.sections.map(s=>({kind:'section',...s}));if(state.templateId==='hospital-death')items.push({kind:'document-photo'});if(state.signers.length)items.push({kind:'signers',signers:state.signers});if(stampSource())items.push({kind:'stamp'});if(state.footer)items.push({kind:'footer'});
    let page=createPage(true,compact);container.appendChild(page);let flow=page.querySelector('.doc-flow'),queue=[...items],guard=0;
    while(queue.length&&guard++<1500){const item=queue.shift();if(item.kind==='section'&&item.type==='heading'&&flow.children.length&&!headingHasRoom(flow,item,queue[0])){page=createPage(false,compact);container.appendChild(page);flow=page.querySelector('.doc-flow')}const node=createFlowBlock(item);if(blockFits(flow,node)){flow.appendChild(node);continue}if(item.kind==='section'&&(item.type==='text'||item.type==='notice')&&plainText(item.content).length>50){const [head,tail]=splitTextToFit(flow,item);if(head){flow.appendChild(createFlowBlock(head));if(tail)queue.unshift(tail);page=createPage(false,compact);container.appendChild(page);flow=page.querySelector('.doc-flow');continue}}if(!flow.children.length){flow.appendChild(node);continue}page=createPage(false,compact);container.appendChild(page);flow=page.querySelector('.doc-flow');queue.unshift(item)}
    return [...container.querySelectorAll('.document-page')];
  };
  let pages=renderAttempt(false);
  if(pages.length===2){const second=pages[1],flow=second.querySelector('.doc-flow');const spill=flow?flow.scrollHeight:9999;const onlySmallTail=spill<=330||flow?.children.length<=2;if(onlySmallTail){const compactPages=renderAttempt(true);if(compactPages.length<=pages.length)pages=compactPages;else pages=renderAttempt(false);}}
  pages.forEach((p,i)=>addDecorations(p,i,pages.length));$('#pageCount').textContent=pages.length+' '+pluralPages(pages.length);$('#workspaceTitle').textContent=state.title||'Новый документ';applyZoom();
}
function pluralPages(n){const a=n%10,b=n%100;return a===1&&b!==11?'страница':a>=2&&a<=4&&(b<12||b>14)?'страницы':'страниц'}

function stampSource(type=state.stampType){if(type!=='custom'&&type===state.portableStampType&&/^data:image\/png;base64,/.test(state.portableStampData||''))return state.portableStampData;if(type==='custom')return /^data:image\/png;base64,/.test(state.customStampData||'')?state.customStampData:'';return STAMP_ASSETS[type]||''}
function setupCustomStampControls(root){if(!root)return;root.innerHTML=`<label>Ссылка на изображение<input data-stamp-url type="url" placeholder="https://example.com/stamp.png" autocomplete="off"></label><div class="custom-stamp-actions"><button type="button" class="secondary-btn" data-stamp-load>Загрузить штамп</button><button type="button" class="ghost-btn" data-stamp-clear>Очистить</button></div><p class="custom-stamp-status" data-stamp-status role="status" aria-live="polite"></p>`;root.querySelector('[data-stamp-load]').onclick=()=>loadCustomStamp(root.querySelector('[data-stamp-url]').value);root.querySelector('[data-stamp-url]').oninput=e=>{e.target.dataset.dirty='true'};root.querySelector('[data-stamp-url]').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();loadCustomStamp(e.target.value)}};root.querySelector('[data-stamp-clear]').onclick=()=>{stampRequest++;stampController?.abort();stampLoading=false;stampMessage='';stampError=false;state.customStampData='';state.customStampUrl='';document.querySelectorAll('[data-stamp-url]').forEach(input=>{delete input.dataset.dirty;input.value='' });syncCustomStampControls();renderPreview();autosave()};syncCustomStampControls()}
function syncCustomStampControls(){document.querySelectorAll('[data-custom-stamp]').forEach(root=>{root.classList.toggle('hidden',state.stampType!=='custom');const input=root.querySelector('[data-stamp-url]');if(!input)return;if(document.activeElement!==input&&!input.dataset.dirty)input.value=state.customStampUrl||'';const load=root.querySelector('[data-stamp-load]');load.disabled=stampLoading;input.disabled=stampLoading;load.textContent=stampLoading?'Загрузка…':'Загрузить штамп';root.querySelector('[data-stamp-clear]').disabled=!state.customStampData&&!stampLoading;const status=root.querySelector('[data-stamp-status]');status.textContent=stampMessage||(state.customStampData?'Штамп сохранён в документе. Можно использовать без повторной загрузки.':'Прямая ссылка на PNG, JPG, WebP или GIF. Для прозрачного фона используйте PNG.');status.classList.toggle('error',stampError);})}
async function stampImageData(blob){if(blob.type&&!/^image\/(png|jpeg|webp|gif)$/i.test(blob.type))throw Error('Поддерживаются PNG, JPG, WebP и GIF. Нужна прямая ссылка на изображение.');const url=URL.createObjectURL(blob);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Не удалось открыть изображение. Проверьте прямую ссылку.'));img.src=url});if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>32000000)throw Error('Изображение слишком большое. Выберите штамп меньшего размера.');let scale=Math.min(1,1024/Math.max(img.naturalWidth,img.naturalHeight)),result;do{const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);result=canvas.toDataURL('image/png');if(result.length<=700000)return result;scale*=.75}while(scale*Math.max(img.naturalWidth,img.naturalHeight)>=192);throw Error('Не удалось подготовить изображение для сохранения. Попробуйте другой файл.')}finally{URL.revokeObjectURL(url)}}
async function loadCustomStamp(value){let url;try{url=new URL(String(value||'').trim());if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error()}catch{stampMessage='Укажите прямую ссылку на изображение, начиная с https://';stampError=true;syncCustomStampControls();return}const request=++stampRequest;stampController?.abort();const controller=new AbortController();stampController=controller;stampLoading=true;stampError=false;stampMessage='Загружаем изображение…';syncCustomStampControls();const timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(url.href,{mode:'cors',credentials:'omit',referrerPolicy:'no-referrer',signal:controller.signal});if(!response.ok)throw Error('Ссылка недоступна (HTTP '+response.status+'). Проверьте адрес изображения.');if(Number(response.headers.get('content-length'))>6*1024*1024)throw Error('Файл слишком большой. Используйте изображение до 6 МБ.');const blob=await response.blob();if(blob.size>6*1024*1024)throw Error('Файл слишком большой. Используйте изображение до 6 МБ.');const data=await stampImageData(blob);if(request!==stampRequest)return;state.customStampData=data;state.customStampUrl=url.href;document.querySelectorAll('[data-stamp-url]').forEach(input=>{delete input.dataset.dirty;input.value=url.href});stampMessage='Штамп загружен и сохранён в документе.';stampError=false;renderPreview();autosave()}catch(e){if(request!==stampRequest)return;stampError=true;stampMessage=e.name==='AbortError'?'Загрузка заняла слишком много времени. Попробуйте другую ссылку.':e instanceof TypeError?'Хостинг не разрешает загрузку изображения. Попробуйте прямую ссылку с другого хостинга.':e.message}finally{clearTimeout(timeout);if(request===stampRequest){stampLoading=false;syncCustomStampControls()}}}

function handleEmblem(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.emblem=r.result;renderPreview();autosave()};r.readAsDataURL(f)}
function autosave(){queueDocumentHistory();clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem('rpm_docs_draft_v3',JSON.stringify(state))}catch(e){toast('Не удалось сохранить черновик в браузере')}},250)}
function restoreDraft(){try{const raw=localStorage.getItem('rpm_docs_draft_v3')||localStorage.getItem('rpm_docs_draft');if(raw)state={...freshState(),...JSON.parse(raw)}}catch(e){}}
function saveVersion(){const all=getHistory();all.unshift({id:Date.now(),savedAt:new Date().toISOString(),data:JSON.parse(JSON.stringify(state))});try{localStorage.setItem('rpm_docs_versions_v3',JSON.stringify(all.slice(0,100)));toast('Документ сохранён в истории');renderSavedList()}catch(e){toast('Недостаточно места в браузере. Экспортируйте архив и удалите ненужные документы.')}}
function getHistory(){try{return JSON.parse(localStorage.getItem('rpm_docs_versions_v3')||localStorage.getItem('rpm_docs_versions')||'[]')}catch(e){return[]}}
function renderSavedList(){const root=$('#savedList'),all=getHistory();root.innerHTML='';if(!all.length){root.innerHTML='<div class="help">Пока нет сохранённых документов.</div>';return}all.forEach(item=>{const d=document.createElement('div');d.className='saved-item';d.innerHTML=`<div><strong>${String(item.data?.quickData?.['статус ордера']||'').includes('закрыт')?'🔒 ':''}${escapeHtml(item.data.title||'Без названия')}</strong><span>${escapeHtml(item.data.code||'')} · ${new Date(item.savedAt).toLocaleString('ru-RU')}</span></div><div class="saved-actions"><button class="mini-btn" data-open>Открыть</button><button class="mini-btn" data-copy>Копия</button><button class="mini-btn danger" data-del>×</button></div>`;d.querySelector('[data-open]').onclick=()=>{state=JSON.parse(JSON.stringify(item.data));migrateState();renderAll();switchPanel('editorPanel');autosave()};d.querySelector('[data-copy]').onclick=()=>{state=JSON.parse(JSON.stringify(item.data));state.code=(state.code||'DOC')+'-COPY';state.title=(state.title||'Документ')+' — копия';migrateState();renderAll();switchPanel('editorPanel');autosave()};d.querySelector('[data-del]').onclick=()=>{localStorage.setItem('rpm_docs_versions_v3',JSON.stringify(all.filter(x=>x.id!==item.id)));renderSavedList()};root.appendChild(d)})}
function exportHistory(){const data={version:3,exportedAt:new Date().toISOString(),documents:getHistory()};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='rpm-docs-history.json';a.click();URL.revokeObjectURL(a.href)}
function importHistory(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(r.result),docs=Array.isArray(data)?data:data.documents;if(!Array.isArray(docs))throw new Error();localStorage.setItem('rpm_docs_versions_v3',JSON.stringify(docs.slice(0,100)));renderSavedList();toast('История импортирована')}catch(err){toast('Не удалось импортировать архив')}};r.readAsText(f);e.target.value=''}

async function waitForExportAssets(root){
  if(document.fonts&&document.fonts.ready){try{await document.fonts.ready}catch(e){}}
  const images=[...root.querySelectorAll('img')];
  await Promise.all(images.map(img=>{
    if(img.complete&&img.naturalWidth)return Promise.resolve();
    return new Promise(resolve=>{const done=()=>resolve();img.addEventListener('load',done,{once:true});img.addEventListener('error',done,{once:true});setTimeout(done,5000)});
  }));
}
async function imageElementToDataURL(img){
  const src=img.currentSrc||img.src||'';
  if(!src||src.startsWith('data:')||src.startsWith('blob:'))return src;
  try{
    const res=await fetch(src,{cache:'force-cache'});
    if(!res.ok)throw new Error('HTTP '+res.status);
    const blob=await res.blob();
    return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)});
  }catch(e){
    return '';
  }
}
async function createExportClone(page){
  const host=document.createElement('div');
  host.className='export-capture-host';
  host.style.cssText='position:fixed;left:-12000px;top:0;width:794px;height:1123px;margin:0;padding:0;transform:none!important;z-index:-99999;pointer-events:none;background:#fff;';
  const clone=page.cloneNode(true);
  clone.style.transform='none';
  clone.style.margin='0';
  clone.style.boxShadow='none';
  clone.style.width='794px';
  clone.style.height='1123px';
  clone.style.flex='none';
  const sourceImgs=[...page.querySelectorAll('img')],cloneImgs=[...clone.querySelectorAll('img')];
  for(let i=0;i<cloneImgs.length;i++){
    const safe=await imageElementToDataURL(sourceImgs[i]||cloneImgs[i]);
    if(safe){cloneImgs[i].src=safe;cloneImgs[i].removeAttribute('crossorigin')}
    else cloneImgs[i].remove();
  }
  host.appendChild(clone);document.body.appendChild(host);
  return {host,clone};
}
async function capturePages(){
  if(state.stampType==='custom'&&stampLoading)throw new Error('Дождитесь загрузки своего штампа.');
  if(typeof window.html2canvas!=='function')throw new Error('html2canvas не загружен');
  clearTimeout(_liveQuickTimer);if($('#quickPanel').classList.contains('active-panel')&&state.templateId)applyQuickData(true);clearTimeout(window._rpmRender);buildPages();await waitForExportAssets($('#pagesContainer'));buildPages();
  const sourcePages=$$('#pagesContainer .document-page');
  if(!sourcePages.length)throw new Error('Нет страниц для экспорта');
  const out=[];
  for(const source of sourcePages){
    const {host,clone}=await createExportClone(source);
    try{
      await waitForExportAssets(clone);
      const canvas=await window.html2canvas(clone,{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#fdfcf9',logging:false,imageTimeout:15000,removeContainer:true,width:794,height:1123,windowWidth:794,windowHeight:1123,scrollX:0,scrollY:0});
      out.push(canvas);
    }finally{host.remove()}
  }
  return out;
}
function canvasToBlob(canvas,type='image/png',quality=1){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Не удалось сформировать изображение')),type,quality))}
function safeBaseName(){return`${(state.code||'document').replace(/[^a-zа-я0-9_-]+/gi,'_')}_${(state.title||'document').replace(/[^a-zа-я0-9_-]+/gi,'_').slice(0,45)}`}
function triggerBlobDownload(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function withExportBusy(buttonId,label,fn){const btn=$(buttonId);const old=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent=label}try{return await fn()}finally{if(btn){btn.disabled=false;btn.textContent=old}}}
async function downloadPNG(){
  return withExportBusy('#pngBtn','Экспорт PNG…',async()=>{
    try{
      const pages=await capturePages(),base=safeBaseName();
      for(let i=0;i<pages.length;i++){
        const blob=await canvasToBlob(pages[i],'image/png');
        const suffix=pages.length>1?`_page-${String(i+1).padStart(2,'0')}`:'';
        triggerBlobDownload(blob,`${base}${suffix}.png`);
        if(pages.length>1)await new Promise(r=>setTimeout(r,350));
      }
      toast(pages.length>1?`PNG: сохранено ${pages.length} страниц`:'PNG сохранён');
    }catch(e){console.error('PNG export error',e);toast((String(e&&e.message||'').includes('Tainted')||String(e&&e.message||'').includes('tainted'))?'Не удалось экспортировать PNG из-за внешнего изображения. Обновите страницу и попробуйте ещё раз.':'Не удалось экспортировать PNG: '+(e.message||'ошибка'))}
  });
}
async function downloadPDF(){
  return withExportBusy('#pdfBtn','Экспорт PDF…',async()=>{
    try{
      if(!window.jspdf||!window.jspdf.jsPDF)throw new Error('jsPDF не загружен');
      const canvases=await capturePages(),{jsPDF}=window.jspdf,pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});
      for(let i=0;i<canvases.length;i++){
        if(i)pdf.addPage('a4','portrait');
        const data=canvases[i].toDataURL('image/jpeg',0.94);
        pdf.addImage(data,'JPEG',0,0,210,297,undefined,'FAST');
      }
      pdf.save(`${safeBaseName()}.pdf`);toast('PDF сохранён');
    }catch(e){console.error('PDF export error',e);toast((String(e&&e.message||'').includes('Tainted')||String(e&&e.message||'').includes('tainted'))?'Не удалось экспортировать PDF из-за внешнего изображения. Обновите страницу и попробуйте ещё раз.':'Не удалось экспортировать PDF: '+(e.message||'ошибка'))}
  });
}
function fileName(ext){return`${safeBaseName()}.${ext}`}

function setZoom(z){zoomFitsWidth=false;zoom=Math.round(z*100)/100;applyZoom()}
function fitZoom(){zoomFitsWidth=true;applyZoom()}
function applyZoom(){
  const pc=$('#pagesContainer'),viewport=$('#pageViewport'),stage=$('.document-stage');if(!pc||!viewport||!stage)return;
  if(zoomFitsWidth){const style=getComputedStyle(stage),available=stage.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight);zoom=Math.max(.2,Math.min(1,Math.floor(available/794*100)/100));}
  const count=pc.querySelectorAll('.document-page').length,nativeHeight=count*1123+Math.max(0,count-1)*24;
  viewport.style.width=(794*zoom)+'px';viewport.style.height=(nativeHeight*zoom)+'px';pc.style.transform=`scale(${zoom})`;pc.style.width='794px';pc.style.height='auto';pc.style.margin='0';$('#zoomLabel').textContent=Math.round(zoom*100)+'%';
  $('#zoomFitBtn')?.setAttribute('aria-pressed',String(zoomFitsWidth));
}
document.addEventListener('DOMContentLoaded',()=>{
  $('#zoomFitBtn').onclick=fitZoom;
  if(window.ResizeObserver){const observer=new ResizeObserver(()=>applyZoom());observer.observe($('.document-stage'))}else window.addEventListener('resize',()=>applyZoom());
});

function formatDate(s){if(!s)return'—';const[y,m,d]=s.split('-');return`${d}.${m}.${y}`}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function escapeAttr(s=''){return escapeHtml(s)}function capitalize(s=''){return s.charAt(0).toUpperCase()+s.slice(1)}
document.addEventListener('DOMContentLoaded',init);

