function warrantCircumstanceKey(){const t=TEMPLATES.find(x=>x.id===state.templateId);return t?.group==='warrant'?extractPlaceholders(state.templateBase||t.sections.map(([type,content])=>({type,content}))).find(k=>k.startsWith('обстоятельств')):null}
function warrantCircumstanceAuthor(){return state.quickData.__warrantIssuerOrg||'Суд штата RPM'}
function warrantCircumstancePrefix(org){return `${org}, рассмотрев представленные материалы, ${org.includes('Суд')?'установил':org.includes('Больница')?'установила':'установило'} `}
