function renderWarrantCircumstances(){const key=warrantCircumstanceKey(),presets=WARRANT_CIRCUMSTANCES[state.templateId];if(!key||!presets)return;const input=Array.from(document.querySelectorAll('#quickFields [data-quick]')).find(el=>el.dataset.quick===key);if(!input)return;input.rows=7;const field=input.parentElement,box=document.createElement('div');box.className='circumstance-field';field.before(box);box.appendChild(field);const label=document.createElement('label');label.className='circumstance-presets';label.textContent='Шаблон обстоятельств';const select=document.createElement('select');select.id='circumstancePreset';select.add(new Option('Свой текст',''));presets.forEach(([id,title])=>select.add(new Option(title,id)));select.value=state.quickData.__circumstancePreset||'';label.appendChild(select);box.prepend(label);select.onchange=()=>{state.quickData.__circumstancePreset=select.value;const preset=presets.find(([id])=>id===select.value);if(preset){const prefix=warrantCircumstancePrefix(warrantCircumstanceAuthor());state.quickData.__circumstancePrefix=prefix;state.quickData[key]=prefix+preset[2];input.value=state.quickData[key]}else delete state.quickData.__circumstancePrefix;scheduleLiveQuick();autosave()};}

