function insertLegalPhrase(){const idx=Number($('#phraseSelect')?.value||0),pair=LEGAL_PHRASES[idx]||LEGAL_PHRASES[0];let target=-1;for(let i=state.sections.length-1;i>=0;i--){if(state.sections[i]?.type==='text'){target=i;break}}if(target<0){state.sections.push({type:'text',content:pair[1],align:'justify',size:'normal'});target=state.sections.length-1}else{const current=String(state.sections[target].content||'').trimEnd();state.sections[target].content=current+(current?'\n\n':'')+pair[1]}renderSections();renderPreview();autosave();toast('Формулировка добавлена в текст')}

async function downloadPNGZip(){
  return withExportBusy('#pngZipBtn','ZIP…',async()=>{
    try{
      if(typeof JSZip==='undefined')throw new Error('JSZip не загружен');
      const pages=await capturePages(),zip=new JSZip(),base=safeBaseName();
      for(let i=0;i<pages.length;i++){const blob=await canvasToBlob(pages[i],'image/png');zip.file(`${base}_page-${String(i+1).padStart(2,'0')}.png`,blob)}
      const out=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}});triggerBlobDownload(out,`${base}_PNG.zip`);toast(`ZIP: ${pages.length} стр.`)
    }catch(e){console.error(e);toast('Не удалось создать PNG ZIP: '+(e.message||'ошибка'))}
  })
}

function setupV16(){
  const root=$('#quickFields');if(root){const live=e=>{const el=e.target;if(!el)return;if(el.matches('[data-quick]')){const key=el.dataset.quick;if(key==='статус ордера'){const closed=String(el.value||'').includes('закрыт');if(closed){state.watermark={...(state.watermark||{}),enabled:true,text:'CONFIDENTIAL',opacity:9,size:84,angle:-28,auto:true}}else if(state.watermark&&state.watermark.auto){state.watermark.enabled=false;state.watermark.auto=false}renderQuickForm()}scheduleLiveQuick()}else if(el.matches('#quickCode,#quickDate,[data-quick-signer-name],[data-quick-signer-role],#quickWarrantIssuerOrg,#quickWarrantIssuerRole,#quickWarrantIssuerName'))scheduleLiveQuick()};root.addEventListener('input',live);root.addEventListener('change',live)}
  if($('#fontInput'))$('#fontInput').onchange=e=>{state.docFont=e.target.value;renderPreview();autosave()};
  const wmUpdate=()=>{state.watermark={...(state.watermark||{}),enabled:$('#watermarkEnabled').checked,text:$('#watermarkText').value,opacity:Number($('#watermarkOpacity').value),size:Number($('#watermarkSize').value),angle:Number($('#watermarkAngle').value),auto:false};renderPreview();autosave()};['watermarkEnabled','watermarkText','watermarkOpacity','watermarkSize','watermarkAngle'].forEach(id=>{const el=$('#'+id);if(el){el.addEventListener('input',wmUpdate);el.addEventListener('change',wmUpdate)}});
  if($('#phraseSelect')){LEGAL_PHRASES.forEach((x,i)=>$('#phraseSelect').add(new Option(x[0],i)));$('#insertPhraseBtn').onclick=insertLegalPhrase}
  
  setInterval(()=>{try{localStorage.setItem('rpm_docs_draft_v3',JSON.stringify(state));if($('#saveStatus'))$('#saveStatus').textContent='Черновик сохранён'}catch(e){}},3000);
  window.addEventListener('beforeunload',()=>{try{localStorage.setItem('rpm_docs_draft_v3',JSON.stringify(state))}catch(e){}});
  renderEditorFields();renderQuickForm();renderPreview();
}
