  new ResizeObserver(fitPreview).observe(stage);fitPreview();
  ['zoomOutBtn','zoomInBtn'].forEach(id=>$('#'+id).addEventListener('click',()=>fit=false));
  if(document.fonts)document.fonts.ready.then(()=>renderPreview());
  $('#templateSearch').addEventListener('input',e=>{const query=e.target.value.trim().toLocaleLowerCase('ru');let found=0;$$('.template-card').forEach(card=>{const match=card.textContent.toLocaleLowerCase('ru').includes(query);card.hidden=!match;if(match)found++});$$('.template-group').forEach(group=>group.hidden=![...group.querySelectorAll('.template-card')].some(c=>!c.hidden));$('#templateSearchEmpty').classList.toggle('hidden',found>0)});
