  block.innerHTML='<h3 class="quick-subtitle">Подпись</h3>';
  state.signers.forEach((s,i)=>{
    const card=document.createElement('div');card.className='quick-signature-card';card.dataset.quickSignatureIndex=i;
    card.innerHTML=`${state.signers.length>1?`<div class="quick-signature-name">${escapeHtml(s.name||'Подписант '+(i+1))}</div>`:''}<label>Способ подписания<select data-quick-signature-mode><option value="auto">Автоматическая</option><option value="manual">Рукописная</option><option value="none">Без подписи</option></select></label><div data-quick-auto><label>Текст подписи<input data-quick-signature-text type="text" value="${escapeAttr(s.signatureText||autoSignature(s.name))}"></label><div class="signature-sample" data-quick-signature-sample>${escapeHtml(s.signatureText||autoSignature(s.name))}</div></div><div data-quick-manual class="hidden"><div class="signature-toolbar"><span class="help">Нарисуйте подпись</span><button class="mini-btn" data-quick-signature-clear type="button">Очистить</button></div><canvas data-canvas width="640" height="190"></canvas></div>`;
    block.appendChild(card);root.appendChild(block);
    const mode=card.querySelector('[data-quick-signature-mode]');mode.value=s.signatureMode||'auto';
    const toggle=()=>{card.querySelector('[data-quick-auto]').classList.toggle('hidden',mode.value!=='auto');card.querySelector('[data-quick-manual]').classList.toggle('hidden',mode.value!=='manual');if(mode.value==='manual')setupSignerCanvas(card.querySelector('canvas'),i,card.querySelector('[data-quick-signature-clear]'))};toggle();
    mode.onchange=()=>{state.signers[i].signatureMode=mode.value;toggle();renderSigners();renderPreview();autosave()};
    card.querySelector('[data-quick-signature-text]').oninput=e=>{state.signers[i].signatureText=e.target.value;card.querySelector('[data-quick-signature-sample]').textContent=e.target.value;renderSigners();renderPreview();autosave()};
  });
